  is_retryable INTEGER NOT NULL DEFAULT 1 CHECK(typeof(is_retryable)='integer' AND is_retryable IN (0,1)),
  pause_reason TEXT  CHECK(pause_reason IS NULL OR typeof(pause_reason)='text' AND length(trim(pause_reason))>0),
  next_attempt_at TEXT CHECK(next_attempt_at IS NULL OR typeof(next_attempt_at)='text' AND length(next_attempt_at)=24 AND (typeof(substr(next_attempt_at,1,10))='text' AND length(substr(next_attempt_at,1,10))=10 AND substr(next_attempt_at,1,10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND CAST(substr(substr(next_attempt_at,1,10),1,4) AS INTEGER) BETWEEN 1 AND 9999 AND CAST(substr(substr(next_attempt_at,1,10),6,2) AS INTEGER) BETWEEN 1 AND 12 AND CAST(substr(substr(next_attempt_at,1,10),9,2) AS INTEGER) BETWEEN 1 AND CASE WHEN CAST(substr(substr(next_attempt_at,1,10),6,2) AS INTEGER)=2 THEN 28+CASE WHEN (CAST(substr(substr(next_attempt_at,1,10),1,4) AS INTEGER)%4=0 AND (CAST(substr(substr(next_attempt_at,1,10),1,4) AS INTEGER)%100<>0 OR CAST(substr(substr(next_attempt_at,1,10),1,4) AS INTEGER)%400=0)) THEN 1 ELSE 0 END WHEN CAST(substr(substr(next_attempt_at,1,10),6,2) AS INTEGER) IN (4,6,9,11) THEN 30 ELSE 31 END) AND substr(next_attempt_at,11) GLOB 'T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z' AND CAST(substr(next_attempt_at,12,2) AS INTEGER) BETWEEN 0 AND 23 AND CAST(substr(next_attempt_at,15,2) AS INTEGER) BETWEEN 0 AND 59 AND CAST(substr(next_attempt_at,18,2) AS INTEGER) BETWEEN 0 AND 59), processing_until TEXT CHECK(processing_until IS NULL OR typeof(processing_until)='text' AND length(processing_until)=24 AND (typeof(substr(processing_until,1,10))='text' AND length(substr(processing_until,1,10))=10 AND substr(processing_until,1,10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND CAST(substr(substr(processing_until,1,10),1,4) AS INTEGER) BETWEEN 1 AND 9999 AND CAST(substr(substr(processing_until,1,10),6,2) AS INTEGER) BETWEEN 1 AND 12 AND CAST(substr(substr(processing_until,1,10),9,2) AS INTEGER) BETWEEN 1 AND CASE WHEN CAST(substr(substr(processing_until,1,10),6,2) AS INTEGER)=2 THEN 28+CASE WHEN (CAST(substr(substr(processing_until,1,10),1,4) AS INTEGER)%4=0 AND (CAST(substr(substr(processing_until,1,10),1,4) AS INTEGER)%100<>0 OR CAST(substr(substr(processing_until,1,10),1,4) AS INTEGER)%400=0)) THEN 1 ELSE 0 END WHEN CAST(substr(substr(processing_until,1,10),6,2) AS INTEGER) IN (4,6,9,11) THEN 30 ELSE 31 END) AND substr(processing_until,11) GLOB 'T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z' AND CAST(substr(processing_until,12,2) AS INTEGER) BETWEEN 0 AND 23 AND CAST(substr(processing_until,15,2) AS INTEGER) BETWEEN 0 AND 59 AND CAST(substr(processing_until,18,2) AS INTEGER) BETWEEN 0 AND 59), last_error TEXT,
  created_at TEXT NOT NULL CHECK(typeof(created_at)='text' AND length(created_at)=24 AND (typeof(substr(created_at,1,10))='text' AND length(substr(created_at,1,10))=10 AND substr(created_at,1,10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND CAST(substr(substr(created_at,1,10),1,4) AS INTEGER) BETWEEN 1 AND 9999 AND CAST(substr(substr(created_at,1,10),6,2) AS INTEGER) BETWEEN 1 AND 12 AND CAST(substr(substr(created_at,1,10),9,2) AS INTEGER) BETWEEN 1 AND CASE WHEN CAST(substr(substr(created_at,1,10),6,2) AS INTEGER)=2 THEN 28+CASE WHEN (CAST(substr(substr(created_at,1,10),1,4) AS INTEGER)%4=0 AND (CAST(substr(substr(created_at,1,10),1,4) AS INTEGER)%100<>0 OR CAST(substr(substr(created_at,1,10),1,4) AS INTEGER)%400=0)) THEN 1 ELSE 0 END WHEN CAST(substr(substr(created_at,1,10),6,2) AS INTEGER) IN (4,6,9,11) THEN 30 ELSE 31 END) AND substr(created_at,11) GLOB 'T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z' AND CAST(substr(created_at,12,2) AS INTEGER) BETWEEN 0 AND 23 AND CAST(substr(created_at,15,2) AS INTEGER) BETWEEN 0 AND 59 AND CAST(substr(created_at,18,2) AS INTEGER) BETWEEN 0 AND 59), updated_at TEXT NOT NULL CHECK(typeof(updated_at)='text' AND length(updated_at)=24 AND (typeof(substr(updated_at,1,10))='text' AND length(substr(updated_at,1,10))=10 AND substr(updated_at,1,10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND CAST(substr(substr(updated_at,1,10),1,4) AS INTEGER) BETWEEN 1 AND 9999 AND CAST(substr(substr(updated_at,1,10),6,2) AS INTEGER) BETWEEN 1 AND 12 AND CAST(substr(substr(updated_at,1,10),9,2) AS INTEGER) BETWEEN 1 AND CASE WHEN CAST(substr(substr(updated_at,1,10),6,2) AS INTEGER)=2 THEN 28+CASE WHEN (CAST(substr(substr(updated_at,1,10),1,4) AS INTEGER)%4=0 AND (CAST(substr(substr(updated_at,1,10),1,4) AS INTEGER)%100<>0 OR CAST(substr(substr(updated_at,1,10),1,4) AS INTEGER)%400=0)) THEN 1 ELSE 0 END WHEN CAST(substr(substr(updated_at,1,10),6,2) AS INTEGER) IN (4,6,9,11) THEN 30 ELSE 31 END) AND substr(updated_at,11) GLOB 'T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z' AND CAST(substr(updated_at,12,2) AS INTEGER) BETWEEN 0 AND 23 AND CAST(substr(updated_at,15,2) AS INTEGER) BETWEEN 0 AND 59 AND CAST(substr(updated_at,18,2) AS INTEGER) BETWEEN 0 AND 59),
  CHECK((status='PROCESSING')=(processing_until IS NOT NULL)),
  PRIMARY KEY(owner_user_id,clinic_id,id),
  UNIQUE(owner_user_id,clinic_id,version_id), FOREIGN KEY(owner_user_id,clinic_id) REFERENCES local_contexts(owner_user_id,clinic_id) ON DELETE RESTRICT
);
CREATE INDEX idx_sync_queue_ready ON sync_queue(owner_user_id,clinic_id,status,next_attempt_at);
CREATE TABLE sync_metadata (
  owner_user_id TEXT NOT NULL CHECK(typeof(owner_user_id)='text' AND length(owner_user_id)=36 AND substr(owner_user_id,9,1)='-' AND substr(owner_user_id,14,1)='-' AND substr(owner_user_id,19,1)='-' AND substr(owner_user_id,24,1)='-' AND length(replace(owner_user_id,'-',''))=32 AND replace(owner_user_id,'-','') NOT GLOB '*[^0-9a-f]*'),
  clinic_id TEXT NOT NULL CHECK(typeof(clinic_id)='text' AND length(clinic_id)=36 AND substr(clinic_id,9,1)='-' AND substr(clinic_id,14,1)='-' AND substr(clinic_id,19,1)='-' AND substr(clinic_id,24,1)='-' AND length(replace(clinic_id,'-',''))=32 AND replace(clinic_id,'-','') NOT GLOB '*[^0-9a-f]*'), stream TEXT NOT NULL CHECK(stream='clinical'),
  cursor TEXT CHECK(cursor IS NULL OR (typeof(cursor)='text' AND length(cursor)>0)),
  revision TEXT NOT NULL CHECK(typeof(revision)='text' AND length(revision) BETWEEN 1 AND 19 AND revision NOT GLOB '*[^0-9]*' AND (revision='0' OR substr(revision,1,1)<>'0') AND (length(revision)<19 OR revision<='9223372036854775807')), updated_at TEXT NOT NULL CHECK(typeof(updated_at)='text' AND length(updated_at)=24 AND (typeof(substr(updated_at,1,10))='text' AND length(substr(updated_at,1,10))=10 AND substr(updated_at,1,10) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND CAST(substr(substr(updated_at,1,10),1,4) AS INTEGER) BETWEEN 1 AND 9999 AND CAST(substr(substr(updated_at,1,10),6,2) AS INTEGER) BETWEEN 1 AND 12 AND CAST(substr(substr(updated_at,1,10),9,2) AS INTEGER) BETWEEN 1 AND CASE WHEN CAST(substr(substr(updated_at,1,10),6,2) AS INTEGER)=2 THEN 28+CASE WHEN (CAST(substr(substr(updated_at,1,10),1,4) AS INTEGER)%4=0 AND (CAST(substr(substr(updated_at,1,10),1,4) AS INTEGER)%100<>0 OR CAST(substr(substr(updated_at,1,10),1,4) AS INTEGER)%400=0)) THEN 1 ELSE 0 END WHEN CAST(substr(substr(updated_at,1,10),6,2) AS INTEGER) IN (4,6,9,11) THEN 30 ELSE 31 END) AND substr(updated_at,11) GLOB 'T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z' AND CAST(substr(updated_at,12,2) AS INTEGER) BETWEEN 0 AND 23 AND CAST(substr(updated_at,15,2) AS INTEGER) BETWEEN 0 AND 59 AND CAST(substr(updated_at,18,2) AS INTEGER) BETWEEN 0 AND 59),
  PRIMARY KEY(owner_user_id,clinic_id,stream), FOREIGN KEY(owner_user_id,clinic_id) REFERENCES local_contexts(owner_user_id,clinic_id) ON DELETE RESTRICT
);
-- Survives removal of cache rows; the client deletes physical files and acknowledges.
CREATE TABLE local_file_cleanup (
  owner_user_id TEXT NOT NULL CHECK(typeof(owner_user_id)='text' AND length(owner_user_id)=36 AND substr(owner_user_id,9,1)='-' AND substr(owner_user_id,14,1)='-' AND substr(owner_user_id,19,1)='-' AND substr(owner_user_id,24,1)='-' AND length(replace(owner_user_id,'-',''))=32 AND replace(owner_user_id,'-','') NOT GLOB '*[^0-9a-f]*'),
  clinic_id TEXT NOT NULL CHECK(typeof(clinic_id)='text' AND length(clinic_id)=36 AND substr(clinic_id,9,1)='-' AND substr(clinic_id,14,1)='-' AND substr(clinic_id,19,1)='-' AND substr(clinic_id,24,1)='-' AND length(replace(clinic_id,'-',''))=32 AND replace(clinic_id,'-','') NOT GLOB '*[^0-9a-f]*'), file_uri TEXT NOT NULL CHECK(typeof(file_uri)='text' AND length(trim(file_uri))>0),
  PRIMARY KEY(owner_user_id,clinic_id,file_uri)
);
-- Raw legacy queue is retained without guessing its account or tenant.
CREATE TABLE legacy_queue_quarantine (
  legacy_rowid INTEGER NOT NULL PRIMARY KEY,
  raw_record TEXT NOT NULL CHECK(json_valid(raw_record)),
  file_uri TEXT,
  reason TEXT NOT NULL DEFAULT 'UNVERIFIED_OWNER_AND_CLINIC'
);

CREATE TRIGGER version_download_insert AFTER INSERT ON local_exam_versions BEGIN UPDATE local_exams SET current_version=(SELECT max(version_number) FROM local_exam_versions WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND exam_id=NEW.exam_id AND verified_at IS NOT NULL) WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND id=NEW.exam_id; END;
CREATE TRIGGER version_download_update AFTER UPDATE OF local_file_uri,verified_at ON local_exam_versions BEGIN
  INSERT OR IGNORE INTO local_file_cleanup SELECT OLD.owner_user_id,OLD.clinic_id,OLD.local_file_uri WHERE OLD.local_file_uri IS NOT NULL AND OLD.local_file_uri IS NOT NEW.local_file_uri;
  UPDATE local_exams SET current_version=(SELECT max(version_number) FROM local_exam_versions WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND exam_id=NEW.exam_id AND verified_at IS NOT NULL) WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND id=NEW.exam_id;
END;
CREATE TRIGGER version_download_delete AFTER DELETE ON local_exam_versions BEGIN
  INSERT OR IGNORE INTO local_file_cleanup SELECT OLD.owner_user_id,OLD.clinic_id,OLD.local_file_uri WHERE OLD.local_file_uri IS NOT NULL;
  UPDATE local_exams SET current_version=(SELECT max(version_number) FROM local_exam_versions WHERE owner_user_id=OLD.owner_user_id AND clinic_id=OLD.clinic_id AND exam_id=OLD.exam_id AND verified_at IS NOT NULL) WHERE owner_user_id=OLD.owner_user_id AND clinic_id=OLD.clinic_id AND id=OLD.exam_id;
END;
CREATE TRIGGER current_version_derived BEFORE UPDATE OF current_version ON local_exams
WHEN NEW.current_version IS NOT (SELECT max(version_number) FROM local_exam_versions WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND exam_id=NEW.id AND verified_at IS NOT NULL)
BEGIN SELECT RAISE(ABORT,'current_version is derived from verified downloads'); END;
CREATE TRIGGER no_initial_download BEFORE INSERT ON local_exams WHEN NEW.current_version IS NOT NULL
BEGIN SELECT RAISE(ABORT,'An initial cached exam has no verified download'); END;
CREATE TRIGGER version_metadata_immutable BEFORE UPDATE ON local_exam_versions
WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.clinic_id IS NOT OLD.clinic_id OR NEW.id IS NOT OLD.id
 OR NEW.exam_id IS NOT OLD.exam_id OR NEW.version_number IS NOT OLD.version_number OR NEW.sha256 IS NOT OLD.sha256
 OR NEW.size_bytes IS NOT OLD.size_bytes OR NEW.mime_type IS NOT OLD.mime_type OR NEW.original_filename IS NOT OLD.original_filename OR NEW.created_at IS NOT OLD.created_at
BEGIN SELECT RAISE(ABORT,'Confirmed version metadata is immutable'); END;
CREATE TRIGGER queue_identity_immutable BEFORE UPDATE ON sync_queue
WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.clinic_id IS NOT OLD.clinic_id OR NEW.id IS NOT OLD.id
 OR NEW.operation IS NOT OLD.operation OR NEW.payload IS NOT OLD.payload OR NEW.exam_id IS NOT OLD.exam_id
 OR NEW.patient_id IS NOT OLD.patient_id OR NEW.version_id IS NOT OLD.version_id OR NEW.request_hash IS NOT OLD.request_hash
 OR NEW.file_uri IS NOT OLD.file_uri OR NEW.sha256 IS NOT OLD.sha256 OR NEW.size_bytes IS NOT OLD.size_bytes
 OR NEW.mime_type IS NOT OLD.mime_type OR NEW.original_filename IS NOT OLD.original_filename
BEGIN SELECT RAISE(ABORT,'Retry must preserve upload identity and content'); END;
CREATE TRIGGER queue_claim_authorized BEFORE UPDATE OF status ON sync_queue
WHEN NEW.status='PROCESSING' AND (NEW.pause_reason IS NOT NULL OR NEW.retry_count>8 OR NEW.is_retryable<>1
 OR NOT EXISTS(SELECT 1 FROM local_contexts WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND access_state='READ_WRITE'))
BEGIN SELECT RAISE(ABORT,'Queue cannot process without write access'); END;
CREATE TRIGGER protect_pending_delete BEFORE DELETE ON sync_queue WHEN OLD.status<>'COMPLETED'
BEGIN SELECT RAISE(ABORT,'Pending uploads require explicit user resolution, not deletion'); END;
CREATE TRIGGER queue_completed_cleanup AFTER UPDATE OF status ON sync_queue WHEN NEW.status='COMPLETED' AND OLD.status<>'COMPLETED'
BEGIN INSERT OR IGNORE INTO local_file_cleanup VALUES(NEW.owner_user_id,NEW.clinic_id,NEW.file_uri); END;
CREATE TRIGGER patient_cache_scope BEFORE INSERT ON local_patients
WHEN EXISTS(SELECT 1 FROM local_contexts WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND role='PATIENT') AND NEW.user_id<>NEW.owner_user_id
BEGIN SELECT RAISE(ABORT,'A patient context caches only its own patient'); END;
CREATE TRIGGER patient_cache_scope_update BEFORE UPDATE OF user_id ON local_patients
WHEN EXISTS(SELECT 1 FROM local_contexts WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND role='PATIENT') AND NEW.user_id<>NEW.owner_user_id
BEGIN SELECT RAISE(ABORT,'A patient context caches only its own patient'); END;
CREATE TRIGGER queue_initial_state BEFORE INSERT ON sync_queue WHEN NEW.status<>'PENDING' OR NEW.retry_count<>0
BEGIN SELECT RAISE(ABORT,'New uploads must start pending with no attempts'); END;
CREATE TRIGGER version_within_server_range BEFORE INSERT ON local_exam_versions
WHEN NEW.version_number>(SELECT latest_server_version FROM local_exams WHERE owner_user_id=NEW.owner_user_id AND clinic_id=NEW.clinic_id AND id=NEW.exam_id)
BEGIN SELECT RAISE(ABORT,'Version exceeds confirmed server version'); END;
CREATE TRIGGER server_version_monotonic BEFORE UPDATE OF latest_server_version ON local_exams
WHEN NEW.latest_server_version<OLD.latest_server_version
BEGIN SELECT RAISE(ABORT,'Confirmed version number cannot go backwards'); END;
CREATE TRIGGER cursor_monotonic BEFORE UPDATE OF revision ON sync_metadata
WHEN length(NEW.revision)<length(OLD.revision) OR (length(NEW.revision)=length(OLD.revision) AND NEW.revision<OLD.revision)
BEGIN SELECT RAISE(ABORT,'Sync revision cannot go backwards'); END;
PRAGMA user_version=2;

CREATE TRIGGER scope_local_contexts BEFORE UPDATE ON local_contexts WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.clinic_id IS NOT OLD.clinic_id BEGIN SELECT RAISE(ABORT,'Local scope is immutable'); END;

CREATE TRIGGER scope_local_patients BEFORE UPDATE ON local_patients WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.clinic_id IS NOT OLD.clinic_id OR NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'Local scope is immutable'); END;

CREATE TRIGGER scope_local_exams BEFORE UPDATE ON local_exams WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.clinic_id IS NOT OLD.clinic_id OR NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'Local scope is immutable'); END;

CREATE TRIGGER scope_local_exam_versions BEFORE UPDATE ON local_exam_versions WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.clinic_id IS NOT OLD.clinic_id OR NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'Local scope is immutable'); END;

CREATE TRIGGER scope_sync_queue BEFORE UPDATE ON sync_queue WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.clinic_id IS NOT OLD.clinic_id OR NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'Local scope is immutable'); END;

CREATE TRIGGER scope_sync_metadata BEFORE UPDATE ON sync_metadata WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.clinic_id IS NOT OLD.clinic_id BEGIN SELECT RAISE(ABORT,'Local scope is immutable'); END;
